const hangarDynamicTranslate=translateDynamic;
translateDynamic=function(text){
 const exact=tr(text);if(exact!==text||settings.language==='ko')return exact;
 let result=hangarDynamicTranslate(text);
 const short=[...skins.map(s=>s[0]),...shipJumpTraits.map(s=>s[0]),'보유 코인','보유 기체','업그레이드','최대 속도','점프 출력','연료 효율','연비','고유 점프','강화 단계','장착 중','최대','다음','확인','사용','강화','점프','도전','미리보기'];
 for(const key of short)result=result.split(key).join(tr(key));
 const n={en:0,ja:1,zh:2}[settings.language];
 result=result.replace(/별 (\d+)개 달성 시 해금/g,(_,v)=>['Unlock at '+v+' stars','星'+v+'個で解放','获得'+v+'颗星后解锁'][n]);
 return result;
};
const hangarLocalizeUI=localizeUI;
const localizedPauseSync=syncPauseControl;
syncPauseControl=function(){const out=localizedPauseSync();const paused=state==='pause'||(['falling','exploding'].includes(state)&&fxPaused);pauseControl.setAttribute('aria-label',tr(paused?'항해 재개':'일시정지'));return out};

const hangarAttributeSources=new WeakMap();
localizeUI=function(){
 hangarLocalizeUI();
 if(!document.createTreeWalker||state==='play')return;
 for(const root of [$('shipUpgradePanel'),$('questPanel'),$('notificationPanel'),$('challengePanel'),$('editorPickerOverlay'),$('gravityDeviceDialog'),$('editorRangeGravityDialog')]){if(!root||root.classList?.contains?.('hidden'))continue;const walker=document.createTreeWalker(root,4);let node;
 while((node=walker.nextNode())){const current=node.nodeValue,old=localizedText.get(node),original=old&&old.translated===current?old.original:current,trimmed=original.trim(),translated=trimmed?original.replace(trimmed,translateDynamic(trimmed)):original;localizedText.set(node,{original,translated,language:settings.language});if(current!==translated)node.nodeValue=translated;}
 }
 for(const root of [document.querySelector('header'),document.querySelector('.cockpit'),$('overlay'),$('mapEditor'),$('shipUpgradePanel'),$('questPanel'),$('notificationPanel'),$('challengePanel'),$('editorPickerOverlay'),$('gravityDeviceDialog'),$('editorRangeGravityDialog')])for(const el of root&&!root.classList?.contains?.('hidden')?[root,...root.querySelectorAll('[aria-label],[title],[placeholder]')]:[]){if(!el.getAttribute)continue;
  let sources=hangarAttributeSources.get(el);if(!sources){sources={};hangarAttributeSources.set(el,sources)}
  for(const key of ['aria-label','title','placeholder']){if((el.id==='jump'&&key==='aria-label')||(el.id==='ghostToggle'&&key==='title'))continue;const value=el.getAttribute(key);if(!value)continue;const old=sources[key],original=old&&old.translated===value?old.original:value,translated=translateDynamic(original);sources[key]={original,translated};if(value!==translated)el.setAttribute(key,translated)}
 }
};
const localizedHangarRender=renderShopInterface;renderShopInterface=function(...args){const out=localizedHangarRender(...args);localizeUI();return out};
const localizedUpgradeRender=renderShipUpgradePanel;renderShipUpgradePanel=function(...args){const out=localizedUpgradeRender(...args);localizeUI();return out};
const localizedLobbyUpdate=updateLobby;updateLobby=function(...args){const out=localizedLobbyUpdate(...args);localizeUI();return out};
