// Earlier modules localized static nodes before the extra dictionary existed.
// Restore their source text once, then rebuild the language cache.
if(document.createTreeWalker){for(const root of [document.querySelector('header'),document.querySelector('.cockpit'),$('note'),$('segment'),document.querySelector('.flight-strip'),$('overlay'),$('mapEditor'),$('shipUpgradePanel'),$('questPanel'),$('notificationPanel'),$('challengePanel'),$('editorPickerOverlay'),$('gravityDeviceDialog'),$('editorRangeGravityDialog')]){const walker=document.createTreeWalker(root,4);let node;while((node=walker.nextNode())){const old=localizedText.get(node);if(old&&node.nodeValue===old.translated)node.nodeValue=old.original;localizedText.delete(node)}}}
